-- Paket ABT "abt-romawi-pihak-28okt" (28 Okt 2026): angka romawi pihak pada sampul pihak banyak (variabel 5847, 5890, 5891, 5892, 5893, 5896, 5897) dihitung dari PERINGKAT pihak dalam tabelnya, bukan dari nilai kolom `urutan` (perkara e-Court menomori urutan bersambung lintas tabel).
-- 7 baris variabel diubah; TIDAK ada fungsi baru (memakai isian_rtf_pihak_peringkat dari paket abt-pihak-urut-sisa-28okt dan isian_rtf_romawi yang sudah ada). Prasyarat: paket abt-pihak-urut-ecourt-27okt dan abt-pihak-urut-sisa-28okt sudah terpasang.
-- PRASYARAT (baca saja) "S|R|C|D|G": S = fungsi isian_rtf_pihak_peringkat (paket sisa 28 Okt) yang isinya persis (harus 1) | R = isian_rtf_romawi dan isian_rtf_pihak_peringkat berperilaku benar (harus 1) | C = baris yang akan diubah (7) yang masih isi LAMA (7 pertama, 0 ulang) | D = yang sudah isi BARU (0 pertama, 7 ulang) | G = baris diubah yang bukan lama bukan baru (harus 0).
-- Sengaja TIDAK mensyaratkan isi persis fungsi/variabel paket lain (mis. isian_rtf_pihak_identitas dan isian_rtf_pihak_utama atau variabel 7047 7048 yang paket lain boleh ubah): hanya yang dipakai paket ini.
-- Benar: "1|1|7|0|0" (pertama) atau "1|1|0|7|0" (pasang ulang).
SELECT CONCAT((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_peringkat' AND MD5(routine_definition)='cc803946c757a9921feb3ce6978eac79'))), '|', IF((isian_rtf_romawi(1)='I' AND isian_rtf_romawi(4)='IV' AND isian_rtf_romawi(9)='IX' AND isian_rtf_romawi(14)='XIV' AND isian_rtf_romawi(21)='XXI' AND isian_rtf_romawi(25)='XXV' AND isian_rtf_romawi(26)='XXVI' AND isian_rtf_romawi(32)='XXXII' AND isian_rtf_romawi(49)='XLIX' AND isian_rtf_romawi(99)='XCIX' AND isian_rtf_romawi(1994)='MCMXCIV' AND isian_rtf_romawi(3999)='MMMCMXCIX' AND isian_rtf_pihak_peringkat(1, 0) IS NULL AND isian_rtf_pihak_peringkat(2, 0) IS NULL AND isian_rtf_pihak_peringkat(3, 0) IS NULL AND isian_rtf_pihak_peringkat(4, 0) IS NULL AND isian_rtf_pihak_peringkat(9, 1) IS NULL AND isian_rtf_pihak_peringkat(NULL, 1) IS NULL AND isian_rtf_pihak_peringkat(1, NULL) IS NULL), 1, 0), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=5847 AND MD5(nama)='084ebdb278787a2b041ebbf9b7d28643' AND data_type='data_sql' AND MD5(sql_query)='750b5eedb7b2906367e3634b00d8ba86') OR (no_var=5890 AND MD5(nama)='5d3655aae7c9da5c687df81526060a80' AND data_type='data_sql' AND MD5(sql_query)='caf06f5d202221f43cad2aac20d5ba32') OR (no_var=5891 AND MD5(nama)='624fc6f2408cb47cfb3f39055a73a6a6' AND data_type='data_sql' AND MD5(sql_query)='807ea57a34d25d01a31eba98558385ee') OR (no_var=5892 AND MD5(nama)='05d78f114c69a34f5d0ce64fda32bf23' AND data_type='data_sql' AND MD5(sql_query)='23d51b287d0a741f043acf10f1d01ff6') OR (no_var=5893 AND MD5(nama)='e0e05fffd029b001a75adec329027fb6' AND data_type='data_sql' AND MD5(sql_query)='8c43fda4b968d9633818635c45069930') OR (no_var=5896 AND MD5(nama)='6161d36eb7c164787ef36f3c32e51de7' AND data_type='data_sql' AND MD5(sql_query)='9526ade0506817a783e4d3b007c91a72') OR (no_var=5897 AND MD5(nama)='c3c0be3c56441cf495202245c3eab22b' AND data_type='data_sql' AND MD5(sql_query)='5a99ef118bbd814f55719b724967c8d4'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=5847 AND MD5(nama)='084ebdb278787a2b041ebbf9b7d28643' AND data_type='data_sql' AND MD5(sql_query)='7978d970d92d74417caa8cb6c6d1942f') OR (no_var=5890 AND MD5(nama)='5d3655aae7c9da5c687df81526060a80' AND data_type='data_sql' AND MD5(sql_query)='45d99e984c60cc496751284501e4014e') OR (no_var=5891 AND MD5(nama)='624fc6f2408cb47cfb3f39055a73a6a6' AND data_type='data_sql' AND MD5(sql_query)='3e65b1909433af8a9b0b3f0164775ee4') OR (no_var=5892 AND MD5(nama)='05d78f114c69a34f5d0ce64fda32bf23' AND data_type='data_sql' AND MD5(sql_query)='6f1e2991004788ec828d697dfee43503') OR (no_var=5893 AND MD5(nama)='e0e05fffd029b001a75adec329027fb6' AND data_type='data_sql' AND MD5(sql_query)='25d59f0ff0e2e2dae049b2c365f01eb6') OR (no_var=5896 AND MD5(nama)='6161d36eb7c164787ef36f3c32e51de7' AND data_type='data_sql' AND MD5(sql_query)='8a1d84d63df12f604a607b9f03e332d6') OR (no_var=5897 AND MD5(nama)='c3c0be3c56441cf495202245c3eab22b' AND data_type='data_sql' AND MD5(sql_query)='de79844c3a06c75d4bd1c56a09fec4c5'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (5847,5890,5891,5892,5893,5896,5897) AND NOT (((no_var=5847 AND MD5(nama)='084ebdb278787a2b041ebbf9b7d28643' AND data_type='data_sql' AND MD5(sql_query)='750b5eedb7b2906367e3634b00d8ba86') OR (no_var=5890 AND MD5(nama)='5d3655aae7c9da5c687df81526060a80' AND data_type='data_sql' AND MD5(sql_query)='caf06f5d202221f43cad2aac20d5ba32') OR (no_var=5891 AND MD5(nama)='624fc6f2408cb47cfb3f39055a73a6a6' AND data_type='data_sql' AND MD5(sql_query)='807ea57a34d25d01a31eba98558385ee') OR (no_var=5892 AND MD5(nama)='05d78f114c69a34f5d0ce64fda32bf23' AND data_type='data_sql' AND MD5(sql_query)='23d51b287d0a741f043acf10f1d01ff6') OR (no_var=5893 AND MD5(nama)='e0e05fffd029b001a75adec329027fb6' AND data_type='data_sql' AND MD5(sql_query)='8c43fda4b968d9633818635c45069930') OR (no_var=5896 AND MD5(nama)='6161d36eb7c164787ef36f3c32e51de7' AND data_type='data_sql' AND MD5(sql_query)='9526ade0506817a783e4d3b007c91a72') OR (no_var=5897 AND MD5(nama)='c3c0be3c56441cf495202245c3eab22b' AND data_type='data_sql' AND MD5(sql_query)='5a99ef118bbd814f55719b724967c8d4')) OR ((no_var=5847 AND MD5(nama)='084ebdb278787a2b041ebbf9b7d28643' AND data_type='data_sql' AND MD5(sql_query)='7978d970d92d74417caa8cb6c6d1942f') OR (no_var=5890 AND MD5(nama)='5d3655aae7c9da5c687df81526060a80' AND data_type='data_sql' AND MD5(sql_query)='45d99e984c60cc496751284501e4014e') OR (no_var=5891 AND MD5(nama)='624fc6f2408cb47cfb3f39055a73a6a6' AND data_type='data_sql' AND MD5(sql_query)='3e65b1909433af8a9b0b3f0164775ee4') OR (no_var=5892 AND MD5(nama)='05d78f114c69a34f5d0ce64fda32bf23' AND data_type='data_sql' AND MD5(sql_query)='6f1e2991004788ec828d697dfee43503') OR (no_var=5893 AND MD5(nama)='e0e05fffd029b001a75adec329027fb6' AND data_type='data_sql' AND MD5(sql_query)='25d59f0ff0e2e2dae049b2c365f01eb6') OR (no_var=5896 AND MD5(nama)='6161d36eb7c164787ef36f3c32e51de7' AND data_type='data_sql' AND MD5(sql_query)='8a1d84d63df12f604a607b9f03e332d6') OR (no_var=5897 AND MD5(nama)='c3c0be3c56441cf495202245c3eab22b' AND data_type='data_sql' AND MD5(sql_query)='de79844c3a06c75d4bd1c56a09fec4c5'))))) AS prasyarat;
